package main

import (
	"fmt"
	"os"
)

const version = "v1.13.0"

func main() {
	args := os.Args[1:]

	// Check for --help
	if hasFlag(args, "--help") || hasFlag(args, "-h") {
		printHelp()
		os.Exit(1)
	}

	// Check for --version
	if hasFlag(args, "--version") || hasFlag(args, "-v") {
		fmt.Println(version)
		os.Exit(0)
	}

	// If no args, show help
	if len(args) == 0 {
		printHelp()
		os.Exit(1)
	}

	// If we get here, we need a TTY for interactive mode
	fmt.Fprintf(os.Stderr, "walk: requires a terminal\n")
	os.Exit(2)
}

func hasFlag(args []string, flag string) bool {
	for _, arg := range args {
		if arg == flag {
			return true
		}
	}
	return false
}

func printHelp() {
	fmt.Println()
	fmt.Printf("  walk %s\n\n", version)
	fmt.Println("  Usage: walk [path]\n")
	fmt.Println("\t\tarrows, hjkl  Move cursor")
	fmt.Println("\t\tenter         Enter directory")
	fmt.Println("\t\tbackspace     Exit directory")
	fmt.Println("\t\tspace         Toggle preview")
	fmt.Println("\t\tesc, q        Exit with cd")
	fmt.Println("\t\tctrl+c        Exit without cd")
	fmt.Println("\t\t/             Fuzzy search")
	fmt.Println("\t\td, delete     Delete file or dir")
	fmt.Println("\t\ty             Copy to clipboard")
	fmt.Println("\t\t.             Hide hidden files")
	fmt.Println("\t\t?             Show help")
	fmt.Println()
	fmt.Println("  Flags:")
	fmt.Println()
	fmt.Println("\t\t--icons        display icons")
	fmt.Println("\t\t--dir-only     show dirs only")
	fmt.Println("\t\t--hide-hidden  hide hidden files")
	fmt.Println("\t\t--preview      display preview")
	fmt.Println("\t\t--with-border  preview with border")
	fmt.Println("\t\t--fuzzy        fuzzy mode")
	fmt.Println()
}
EOF"}

